import os,json,socket,ssl,shutil,ipaddress,glob,urllib.request,urllib.error,datetime
H="serveriptv.duckdns.org"; IP="146.59.145.3"
d={"host":H,"date_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"local_user_euid":os.geteuid()}
for p in ["/","/srv/projects","/srv/projects/skill-universal","/var/lib/docker"]:
    try:
        u=shutil.disk_usage(p)
        d["disk_"+p.replace("/","_")]={"total_gib":round(u.total/2**30,2),"used_gib":round(u.used/2**30,2),"free_gib":round(u.free/2**30,2)}
    except Exception as e:d["disk_"+p.replace("/","_")]={"error":type(e).__name__}
try:
    ip=set(x[4][0] for x in socket.getaddrinfo(H,443,proto=socket.IPPROTO_TCP))
    d["dns"]={"addresses":sorted(ip),"matches_vps":IP in ip,"all_public":all(ipaddress.ip_address(x).is_global for x in ip)}
except Exception as e:d["dns"]={"error":type(e).__name__}
d["tools_present"]={x:os.path.isfile(p) for x,p in [("nginx","/usr/sbin/nginx"),("certbot","/usr/bin/certbot"),("docker","/usr/bin/docker"),("podman","/usr/bin/podman"),("curl","/usr/bin/curl"),("jellyfin","/usr/bin/jellyfin")]}
d["jellyfin_roots"]={p:os.path.exists(p) for p in ["/srv/projects/jellyfin","/srv/projects/Jellyfin","/etc/systemd/system/jellyfin.service","/etc/letsencrypt/live/"+H+"/fullchain.pem"]}
d["permissions"]={"srv_projects_write":os.access("/srv/projects",os.W_OK),"nginx_conf_write":os.access("/etc/nginx/conf.d",os.W_OK)}
d["nginx_conf_files"]={}
for root in ["/etc/nginx/conf.d/*.conf","/etc/nginx/sites-enabled/*"]:
    for p in glob.glob(root):
        if not os.path.isfile(p):continue
        try:
            s=open(p,encoding="utf-8",errors="ignore").read()
            d["nginx_conf_files"][os.path.basename(p)]={"contains_target":H in s,"proxy_pass":("proxy_pass" in s),"listen_443":("443" in s)}
        except Exception as e:d["nginx_conf_files"][os.path.basename(p)]={"error":type(e).__name__}
try:
    ctx=ssl.create_default_context()
    with socket.create_connection((H,443),timeout=7) as sock:
        with ctx.wrap_socket(sock,server_hostname=H) as tls:
            c=tls.getpeercert()
            d["https"]={"verified":True,"subject":c.get("subject"),"issuer":c.get("issuer"),"notAfter":c.get("notAfter"),"sans":c.get("subjectAltName",[])[:15]}
except ssl.SSLCertVerificationError as e:d["https"]={"verified":False,"verify_code":getattr(e,"verify_code",None),"verify_message":str(getattr(e,"verify_message",e))[:170]}
except Exception as e:d["https"]={"verified":False,"error":type(e).__name__}
for proto in ["http","https"]:
    try:
        req=urllib.request.Request(proto+"://"+H+"/System/Info/Public",headers={"User-Agent":"Ferrari-readonly-TLS-check"})
        with urllib.request.urlopen(req,timeout=5) as res:
            ctype=res.headers.get("Content-Type","")
            body=res.read(1200)
            d[proto+"_probe"]={"code":res.status,"content_type":ctype,"Jellyfin_in_body":b"Jellyfin" in body}
    except urllib.error.HTTPError as e:d[proto+"_probe"]={"code":e.code}
    except Exception as e:d[proto+"_probe"]={"error":type(e).__name__}
print(json.dumps(d,sort_keys=True,ensure_ascii=True))
